"""PPR result record."""

from __future__ import annotations

from dataclasses import dataclass


@dataclass
class PPRResult:
    """Outcome of a pairwise reduction run.

    Attributes:
        seed_original_tokens: Tokens in the original seed program.
        seed_reduced_tokens: Tokens in the reduced seed program.
        variant_original_tokens: Tokens in the original variant program.
        variant_reduced_tokens: Tokens in the reduced variant program.
        diff_original_tokens: Size of the token-level diff before reduction.
        diff_reduced_tokens: Size of the token-level diff after reduction.
        num_tests: Property tests spent on both programs together.
        seed_source: The reduced seed program.
        variant_source: The reduced variant program.
        iterations: Fixpoint iterations the driver needed.
    """

    seed_original_tokens: int = 0
    seed_reduced_tokens: int = 0
    variant_original_tokens: int = 0
    variant_reduced_tokens: int = 0
    diff_original_tokens: int = 0
    diff_reduced_tokens: int = 0
    num_tests: int = 0
    seed_source: str = ""
    variant_source: str = ""
    iterations: int = 0

    @property
    def seed_ratio(self) -> float:
        """Fraction of the seed's tokens that was removed."""
        return _ratio(self.seed_original_tokens, self.seed_reduced_tokens)

    @property
    def variant_ratio(self) -> float:
        """Fraction of the variant's tokens that was removed."""
        return _ratio(self.variant_original_tokens, self.variant_reduced_tokens)

    @property
    def diff_ratio(self) -> float:
        """Fraction of the pairwise difference that was removed."""
        return _ratio(self.diff_original_tokens, self.diff_reduced_tokens)

    @property
    def total_original_tokens(self) -> int:
        """Tokens in both original programs."""
        return self.seed_original_tokens + self.variant_original_tokens

    @property
    def total_reduced_tokens(self) -> int:
        """Tokens in both reduced programs."""
        return self.seed_reduced_tokens + self.variant_reduced_tokens

    def as_dict(self) -> dict:
        """Return the metrics (without the sources) as a plain dictionary."""
        return {
            "seed_original_tokens": self.seed_original_tokens,
            "seed_reduced_tokens": self.seed_reduced_tokens,
            "variant_original_tokens": self.variant_original_tokens,
            "variant_reduced_tokens": self.variant_reduced_tokens,
            "diff_original_tokens": self.diff_original_tokens,
            "diff_reduced_tokens": self.diff_reduced_tokens,
            "num_tests": self.num_tests,
            "iterations": self.iterations,
        }


def _ratio(original: int, reduced: int) -> float:
    """Fraction removed, guarding against an empty original."""
    if original == 0:
        return 0.0
    return 1.0 - (reduced / original)

